INSERT INTO `ingreso_salida` (`id_ingreso_salida`, `id_bodega`, `fecha_ingreso_salida`, `id_proveedor`, `hoja_ruta`, `tipo_documento`, `nro_tipo_documento`, `doc_constancia`, `nro_doc_constancia`, `observaciones`, `tipo_adquisicion`, `id_gestion`, `nro_correlativo`, `fecha_ingreso_sistema`, `doc_upload`, `estado_ingreso_salida`, `id_apertura`, `id_sub_apertura`, `log_ingreso_salida`) VALUES
(1, 2, '2025-04-02', 2, 'SDAFP-928/2025', '1', '25/2025', '1', '1939', 'LA AQUISICION DE OTROS REPUESTOS Y ACCESORIOS PARA EL MANTENIMIENTO PREVENTIVO DE LA CAMIONETA TOYOTA HIL.UX CON PLACA DE CONTROL 3030-FCD', 1, 1, 1, '2025-05-06', NULL, 1, 17, 0, 'CREADO|06/05/2025 14:27:38|travelnestor03@gmail.com,MODIFICADO|26/06/2025 16:39:14|travelnestor03@gmail.com,MODIFICADO|26/06/2025 16:39:41|travelnestor03@gmail.com,MODIFICADO|26/06/2025 16:40:42|travelnestor03@gmail.com,MODIFICADO|26/06/2025 16:40:57'),
(2, 2, '2025-05-13', 14, 'SDAFP-1876/2025', '1', '46/2025', '1', '000008', 'LA ADQUISICIÓN DE SEMILLAS DE ATRIPLEX Y ALKAR ES PARA LA PRODUCCIÓN DE 5000 PLANTINES DE ESPECIES HALÓFITOS LA MISMA SERA ENTREGADOS AL TÉCNICO VI VERISTA PARA CUMPLIR CON LOS OBJETIVOS TRAZADOS POR EL PROYECTO APLI. DE MEDIDAS FITO AMBIENTALES ANTE EL CAMBIO CLIMÁTICO 8 MUNICIPIOS DE LA CUENCA POOPÓ', 1, 1, 2, '2025-05-19', NULL, 1, 11, 0, 'CREADO|19/05/2025 13:54:50|travelnestor03@gmail.com,MODIFICADO|03/06/2025 15:43:08|travelnestor03@gmail.com,MODIFICADO|03/06/2025 15:43:20|travelnestor03@gmail.com,MODIFICADO|05/06/2025 15:08:24|travelnestor03@gmail.com'),
(3, 19, '2025-05-19', 17, 'SDAFP-1988/2025', '1', '78/2025', '1', '1', 'LA COMPRA DE LOS POSTES DE MADERA DE EUCALIPTO TRATADO, ES NECESARIO REALIZAR TRABAJOS DE EXTENSIÓN DE REDES ELÉCTRICAS QUE BENEFICIARAN A TRES COMUNIDADES DEL AREA DISPERSA DEL DEPARTAMENTO DE ORURO POR TANTO ES NESESARIO DISPONER DE POSTES PARA LINEAS ELECTRICAS, CON EL CUAL SE PRETENDE ATENDER LOS COMPROMISOS ADQUIRIDOS EN LA SUSCRIPCIÓN DE CONVENIOS INTER GUBERNATIVOS CON LAS COMUNIDADES QUE ESTÁN DENTRO DE LOS MUNICIPIOS ATREVES DEL PROGRAMA DE APOYO A LA ELECTRIFICACION DEPARTAMENTAL', 1, 1, 1, '2025-05-22', NULL, 1, 64, 0, 'CREADO|22/05/2025 10:45:44|travelnestor03@gmail.com'),
(4, 1, '2025-02-03', 19, 'SDAFP-299/2025', '1', '06/2025', '1', '263', 'PROGRAMA PARA SOCIALIZAR LAS DIFERENTES ACTIVIDADES EN CONMEMORACION AL 244 ANIVERSARIO DE LA GESTA LIBERTARIA DEL 10 DE FEBRERO DE 1781 ORGANIZADA POR EL GOBIERNO AUTONOMO DEPARTAMENTAL DE ORURO', 1, 1, 1, '2025-05-23', NULL, 1, 6, 0, 'CREADO|23/05/2025 14:24:02|pachecowilma36@gmail.com'),
(5, 1, '2025-02-03', 20, 'SDAFP-285/2025', '1', '4/2025', '1', '2', 'BOLSAS ECOLOGICAS PARA SU DISTRIBUCION A LOS PARTICIPANTES DE LAS DIFERENTES CAPACITACIONES Y TALLERES QUE REALIZARA EL PROYECTO', 1, 1, 2, '2025-05-23', NULL, 1, 8, 0, 'CREADO|23/05/2025 14:45:00|pachecowilma36@gmail.com'),
(6, 1, '2025-02-03', 20, 'SDAFP-400/2025', '1', '5/2025', '1', '1', 'PIN PARTE DEL PROGRAMA GENERAL DEL  10 FEBRERO QUE SE ENTREGARA A LAS DIFERENTES AUTORIDADES INSTITUCIONAL  Y POBLACION EN GENERAL CON EL FIN DE FOMENTAR EL CIVISMO Y RELEVANCIA DE ESTA FECHA HISTORICA', 1, 1, 3, '2025-05-23', NULL, 1, 39, 0, 'CREADO|23/05/2025 14:49:15|pachecowilma36@gmail.com'),
