(1, 2, '2025-01-01', 1, 'INV INICIAL', '4', '0', 4, '0', 'INV INICIAL', 1, 1, 1, '2025-03-06', '1.pdf', 1, NULL, 1, 0),
(2, 1, '2025-02-28', 3, 'SDAFP-141/2025', '1', '17/2025', 1, '129', 'PAPEL PARA USO DEL PERSONAL DEPENDIENTE DEL P ROGRAMA PUESTO QUE ES DE NECESIDAD INDISPENSABLE EN LAS OFICINAS, PARA EL DESARROLLO DE LAS FUNCIONES LABORALES', 1, 1, 1, '2025-05-07', '2.pdf', 1, 'CREADO|07/05/2025 09:29:00|pachecowilma36@gmail.com', 39, 0),
(3, 1, '2025-03-21', 4, 'SDAFP-727/2025', '1', '22/2025', 1, '4', '', 1, 1, 2, '2025-05-12', '3.pdf', 1, 'CREADO|12/05/2025 15:12:35|pachecowilma36@gmail.com,MODIFICADO|12/05/2025 15:18:06|pachecowilma36@gmail.com,MODIFICADO|12/05/2025 16:34:37|pachecowilma36@gmail.com,MODIFICADO|12/05/2025 16:34:39|pachecowilma36@gmail.com,MODIFICADO|12/05/2025 16:49:19|pachecowilma36@gmail.com,MODIFICADO|12/05/2025 16:49:20|pachecowilma36@gmail.com', 17, 0),
(4, 1, '2025-03-24', 6, 'SDAFP-733/2025', '1', '23/2025', 1, '30', 'LA COMPRA DE PAPEL BOND PARA EL SERVICIO DEPARTAMENTAL DE AGUAS CUENCAS Y RIEGOS SEDACYR QUE SERA DISPUESTA PARA EL USO EXCLUSIVO DEL PERSONAL TECNICO Y ADMINISTRATIVO DEL SERVICIO', 1, 1, 3, '2025-05-12', '4.pdf', 1, 'CREADO|12/05/2025 17:13:25|pachecowilma36@gmail.com,MODIFICADO|13/05/2025 10:11:07|pachecowilma36@gmail.com,MODIFICADO|13/05/2025 12:08:06|travelnestor03@gmail.com', 10, 0),
(5, 1, '2025-04-04', 7, 'SDAFP-981/2025', '1', '29/2025', 1, '2389 - 2388', 'SE SOLICITA LA COMPRA DE UTILES DE ESCRITORIO Y OFICINA, PARA EL PROGRAMA DE FORTALECIMIENTO DE FISCALIZACION Y CONTROL DE REGALIAS MINERAS EN EL DEPARTAMENTO DE ORURO, PUESTO QUE SON DE NECESIDAD INDISPENSABLE EN LAS OFICINAS, PARA EL DESARROLLO DE LAS FUNCIONES LABORALES, PARA ASI CONTRIBUIR  Y MEJORAR LA CALIDAD RELEVANCIA Y CONDICIONES DE TRABAJO, DOTANDO DE MATERIAL E INSUMOS NECESARIOS PARA SU RESPECTIVO DESARROLLO DE SUS ACTIVIDADES DE MANERA EFICIENTE Y EFICAZ PROPUESTA EN LA GESTION 2025', 1, 1, 4, '2025-05-14', '5.pdf', 1, 'CREADO|14/05/2025 15:13:19|pachecowilma36@gmail.com', 39, 0),
(6, 19, '2025-04-29', 5, 'SDAFP-1781/2025', '1', '43/2025', 1, '8-9-10-11-12', 'SE SOLICITA LA ADQUISICION DE MATERIALES PARA AMBIENTES DEL GOBIERNO AUTONOMO DEPARTAMENTAL DE ORURO ESTA SOLICITUD ES PARA REALIZAR EL MANTENIMIENTO Y DAR UNA MEJOR APARIENCIA AL EDIFICIO CENTRAL', 1, 1, 2, '2025-05-14', '6.pdf', 1, 'CREADO|14/05/2025 16:33:06|travelnestor03@gmail.com,MODIFICADO|17/06/2025 09:39:18|travelnestor03@gmail.com', 4, 0),
(7, 1, '2025-04-14', 8, 'SDAFP-1377/2025', '1', '33/2025', 1, '24', 'SE SOLICITA LA COMPRA DE MATERIAL DE ESCRITORIO Y OFICINA ES PARA USO EXCLUSIVO DEL PERSONAL DE LA DIRECCION DEL SERVICIO DEPARTAMENTAL AGROPECUARIO DEPENDIENTE DE LA SECRETARIA DEPARTAMENTAL DE DESARROLLO PRODUCTIVO E INDUSTRIA DEL GOABIERNO AUTONOMO DPTAL DE ORURO PARA LA PRESENTE GESTION', 1, 1, 5, '2025-05-15', '7.pdf', 1, 'CREADO|15/05/2025 09:28:40|pachecowilma36@gmail.com', 18, 0),
(8, 1, '2025-04-10', 9, 'SDAFP-1377/2025', '1', '34/2025', 1, '464', 'SE SOLICITA LA COMPRA DE MATERIAL DE ESCRITORIO Y OFICINA ES PARA USO EXCLUSIVO DEL PERSONAL DE LA DIRECCION DEL SERVICIO DEPARTAMENTAL AGROPECUARIO DEPENDIENTE DE LA SECRETARIA DPTAL DE DESARROLLO PRODUCTIVO E INDUSTRIA DEL GOBIERNO AUTONOMO DPTAL DE ORURO PARA LA PRESENTE GESTION', 1, 1, 6, '2025-05-15', '8.pdf', 1, 'CREADO|15/05/2025 09:49:04|pachecowilma36@gmail.com', 18, 0),
(9, 1, '2025-04-10', 7, 'SDAFP-1377/2025', '1', '35/2025', 1, '2447', 'SE SOLICITA LA COMPRA DE MATERIAL DE ESCRITORIOY OFICINA ES PARA USO EXCLUSIVO DEL PERSONAL DE LA DIRECCION DEL SERVICIO DEPARTAMENTAL AGROPECUARIO DEPENDIENTE DE LA SECRETARIA DPTAL DE DESARROLLO PRODUCTIVO E INDUSTRIA DEL GOBIERNO AUTONOMO DPTAL DE ORURO PARA LA PRESENTE GESTION', 1, 1, 7, '2025-05-15', '9.pdf', 1, 'CREADO|15/05/2025 10:05:36|pachecowilma36@gmail.com', 18, 0),
