INSERT INTO `partida` (`id_partida`, `descripcion`, `contador`) VALUES
(25500, 'GASTOS POR CONCEPTO DE AVISOS EN RADIODIFUSORAS, TELEVISION, PERIODICOS, INTERNET, CONTRATOS PUBLICITARIOS Y PROMOCIONES POR ALGUN MEDIO DE DIFUCION, INCLUYE MATERIALES PROMOCIONALES, INFORMATIVO, GIGANTOGRAFIAS, IMAGENES INSTITUCIONALES Y/O COMERCIALES, Y OTROS RELACIONADOS', NULL),
(25600, 'GASTOS QUE SE REALIZAN POR TRABAJOS DE DIAGRAMACION, IMPRESION, COMPAGINACION, ENCUADERNACION, FOTOCOPIA Y OTROS EFECTUADOS POR TERCEROS INCLUYE LOS GASTOS POR REVELADO Y COPIADO DE FOTOGRAFIAS SLIDES Y OTROS', NULL),
(31200, 'Alimentos para Animales Gastos destinados a la adquisición de forrajes y otros alimentos para animales de propiedad de instituciones públicas; alimentación de los animales de propiedad del Ejército y de la Policía Boliviana, parques zoológicos, laboratorios de experimentación y otros.', 1002),
(31300, 'Productos Agrícolas, Pecuarios y Forestales Gastos para la adquisición de granos básicos, frutas y flores silvestres, goma, caña, semillas y otros productos agroforestales y agropecuarios en bruto; además, gastos por concepto de adquisición de maderas de construcción, puertas, ventanas, vigas, callapos, durmientes manufacturados o no, y todo otro producto proveniente de esta rama, incluido carbón vegetal. Incluye gastos por la compra de ganado y otros animales vivos, destinados al consumo, repoblamiento, mejoramiento genético o para usos industriales y científicos; incluye productos derivados de los mismos, como ser leche, huevos, lana, miel, pieles y otros.', 2000),
(32100, 'Papel Gastos destinados a la adquisición de papel de escritorio y otros.', 3012),
(32200, 'Productos de Artes Gráficas Gastos para la adquisición de productos de artes gráficas y otros relacionados. Incluye gastos destinados a la adquisición de artículos hechos de papel y cartón.', 4006),
(32400, 'Textos de Enseñanza Gastos destinados a la compra de libros para uso docente.', 5000),
(32500, 'GASTOS PARA LA COMPRA Y SUSCRIPCION DE PERIODICOS Y BOLETINES, INCLUYE GACETAS OFICIALES', NULL),
(33100, 'GASTOS DESTINADOS PARA LA COMPRA DE HILADOS, TELAS DE LINO ALGODON, SEDA, LANA Y FIBRAS ARTIFICIALES, NO UTILIZADOS AUN EN PROCESOS DE CONFECCION', NULL),
(33200, 'GASTOS DESTINADOS A LA ADQUISICION DE TAPICES, ALFOMBRAS, SABANAS, TOALLAS, SACOS DE FIBRAS COLCHONES, CARPAS, CORTINAS Y OTROS TEXTILES SIMILARES', NULL),
(33300, 'Prendas de Vestir Gastos destinados a la adquisición de uniformes, vestimenta de diversos tipos, ropa de trabajo, distintivos y accesorios, independientemente del material de fabricación y otras de seguridad industrial de trabajo establecidas por disposiciones en vigencia.', 6000),
(33400, 'Calzados Gastos destinados a la compra de calzados o zapatos complementarios de uniformes y los de uso exclusivo de servidores públicos que, por razones de seguridad industrial de trabajo establecidas por disposiciones en vigencia.', 7000),
(34100, 'Combustibles, Lubricantes, Derivados y otras Fuentes de Energía Gastos para la adquisición de petróleo crudo y parcialmente refinado, gasolina, kerosene, alcohol, aceites, grasas, fuel-oil, diésel, alquitrán, energía eléctrica y otros, como gas y cemento asfáltico. Se excluye la compra de leña y carbón. Se desagrega en: 34110 Combustibles, Lubricantes y Derivados para consumo 34120 Combustibles, Lubricantes y Derivados para comercialización 34130 Energía Eléctrica para Comercialización.', 8007),
(34110, 'Combustibles, Lubricantes y Derivados para consumo', NULL),
(34200, 'Productos Químicos y Farmacéuticos Gastos para la adquisición de compuestos químicos, tales como ácidos, sales, bases industriales, oxígeno, salitres, calcáreos, pinturas, colorantes, pulimentos; abonos y fertilizantes destinados a labores agrícolas; insecticidas, fumigantes y otros utilizados en labores agropecuarias; medicamentos e insumos para hospitales, clínicas, policlínicas y dispensarios, incluyendo productos básicos para botiquines y los utilizados en veterinaria. Además de los insumos requeridos en la construcción, remodelación y mantenimiento de activos fijos y otros materiales químicos, anticongelantes.', 9002),
(34300, 'Llantas y Neumáticos Gastos destinados a la compra de aros, llantas y neumáticos para utilización en los equipos de tracción, transporte y elevación.', 10000),
(34400, 'Productos de Cuero y Caucho Gastos destinados a la compra de cueros, pieles, curtidos y sin curtir; maletines, portafolios y otros artículos confeccionados con cuero; además de artículos elaborados con caucho, excepto prendas de vestir, llantas y cámaras de aire.', 11000),
(34500, 'Productos de Minerales no Metálicos y Plásticos Gastos por la adquisición de productos de arcilla como macetas, floreros, ceniceros, adornos y otros. Comprende además productos de vidrio como floreros, adornos y vidrio plano. Productos elaborados en loza y porcelana como ser: jarros, inodoros, lavamanos y otros. Adquisición de cemento, cal y yeso para construcción, remodelación o mantenimiento de edificaciones públicas. Compra de tubos sanitarios, bloques, tejas y otros productos elaborados con cemento. Incluye la adquisición de productos en cuya elaboración se utilizaron minerales no metálicos; además de tubos utilizados en instalaciones eléctricas y sanitarias, envases, mochilas para fumigación y otros productos en cuya elaboración se utilizó material plástico. Se excluye aquellos considerados como material de escritorio.', 12003),
(34600, 'Productos Metálicos Gastos destinados a la adquisición de lingotes, planchas, planchones, hojalata, perfiles, alambres, varillas y otros, siempre que sean de hierro o acero. Incluye productos elaborados con base en aluminio, cobre, zinc, bronce y otras aleaciones; además de envases y otros artículos de hojalata, ferretería, estructuras metálicas acabadas y demás productos metálicos. Se excluye la compra de repuestos y/o accesorios de un activo.', 13000),
(34700, 'gastos destinados a la adquisición de estaño , plomo, oro, plata, wólfram, zinc y otros minerales metálicos; carbón minerales en todas sus variedades: piedra , arcilla, arena y grava para la construcción en general, ademas de diversos metaloides', NULL),
(34800, 'Herramientas Menores Gastos para la adquisición de herramientas y equipos menores para uso agropecuario, industrial, de transporte, de construcción, tales como destornilladores, alicates, martillos, tenazas, serruchos, picos, palas, tarrajas y otras herramientas menores no activables.', 14000),
(39100, 'Material de Limpieza e Higiene Gastos destinados a la adquisición de materiales como jabones, detergentes, desinfectantes, paños, ceras, cepillos, escobas y otros.', 15026),
(39300, 'Utensilios de Cocina y Comedor Gastos destinados a la adquisición de menaje de cocina y vajilla de comedor a ser utilizada en hospitales, hogares de niños, asilos y otros.', 16000),
(39400, 'Instrumental Menor Médico-Quirúrgico Gastos destinados a la compra de estetoscopios, termómetros, probetas, desfibriladores, además de material y útiles menores médicos quirúrgicos utilizados en hospitales, clínicas, establecimientos de salud, veterinarias, líneas aéreas y demás dependencias médicas del sector público. Incluye implementos de bioseguridad.', 17001),
(39500, 'Útiles de Escritorio y Oficina Gastos destinados a la adquisición de útiles de escritorio como ser: tintas, lápices, bolígrafos, engrapadoras, perforadoras, calculadoras, medios magnéticos, tóner para impresoras y fotocopiadoras y otros destinados al funcionamiento de oficinas.', 18119),
(39700, 'Útiles y Materiales Eléctricos Gastos para la adquisición de focos, cables eléctricos y de transmisión de datos, sockets, tubos fluorescentes, accesorios de radios, lámparas de escritorio, electrodos, planchas, linternas, conductores, aisladores, fusibles, baterías, pilas, interruptores, conmutadores, enchufes y otros relacionados.', 19000),
(39800, 'Gastos destinados a compra de repuestos y accesorios para los equipos comprendidos en el Subgrupo 43000. Se exceptúan las llantas y neumáticos y los clasificados en las partidas anteriores.', 20004),
(39900, 'Otros Materiales y Suministros Gastos por acuñación de monedas e impresión de billetes, vituallas por atención de emergencias, desastres naturales y todos aquellos materiales y suministros que no se clasificaron en las partidas anteriores.', 30000),
(39990, 'Otros Materiales y Suministros Gastos por acuñación de monedas e impresión de billetes, vituallas por atención de emergencias, desastres naturales y todos aquellos materiales y suministros que no se clasificaron en las partidas anteriores.', NULL);
